"""
Knowledge Processing Utilities
Supporting utility classes for BaseTreeDeepResearchKnowledge system.
"""

import json
import hashlib
import threading
from typing import Dict, List, Any, Optional, Tuple, Union
from dataclasses import dataclass, field
from datetime import datetime
from concurrent.futures import ThreadPoolExecutor, as_completed
from pathlib import Path

from loguru import logger


@dataclass
class ProcessingStats:
    """Statistics for knowledge processing operations."""
    start_time: datetime = field(default_factory=datetime.now)
    end_time: Optional[datetime] = None
    total_nodes: int = 0
    processed_nodes: int = 0
    failed_nodes: int = 0
    total_papers: int = 0
    processed_papers: int = 0
    failed_papers: int = 0
    errors: List[str] = field(default_factory=list)

    def add_error(self, error: str) -> None:
        """Add error to statistics."""
        self.errors.append(f"{datetime.now()}: {error}")
        logger.error(error)

    def mark_completed(self) -> None:
        """Mark processing as completed."""
        self.end_time = datetime.now()

    def get_duration(self) -> Optional[float]:
        """Get processing duration in seconds."""
        if self.end_time:
            return (self.end_time - self.start_time).total_seconds()
        return None

    def get_summary(self) -> Dict[str, Any]:
        """Get processing summary."""
        return {
            "duration_seconds": self.get_duration(),
            "nodes": {
                "total": self.total_nodes,
                "processed": self.processed_nodes,
                "failed": self.failed_nodes,
                "success_rate": self.processed_nodes / max(self.total_nodes, 1)
            },
            "papers": {
                "total": self.total_papers,
                "processed": self.processed_papers,
                "failed": self.failed_papers,
                "success_rate": self.processed_papers / max(self.total_papers, 1)
            },
            "error_count": len(self.errors)
        }


class KnowledgeTreeValidator:
    """Validator for knowledge tree structures."""

    REQUIRED_NODE_FIELDS = {'name', 'label', 'children', 'description'}
    OPTIONAL_NODE_FIELDS = {'kn_type', 'upstream_path', 'nodeUid', 'sourceList'}

    @classmethod
    def validate_tree(cls, tree: Dict[str, Any]) -> Tuple[bool, List[str]]:
        """
        Validate knowledge tree structure.

        Args:
            tree: Tree structure to validate

        Returns:
            Tuple of (is_valid, error_messages)
        """
        errors = []

        if not isinstance(tree, dict):
            errors.append("Tree must be a dictionary")
            return False, errors

        cls._validate_node(tree, errors, path="root")

        return len(errors) == 0, errors

    @classmethod
    def _validate_node(cls, node: Dict[str, Any], errors: List[str], path: str) -> None:
        """Validate a single node recursively."""
        # Check required fields
        for field in cls.REQUIRED_NODE_FIELDS:
            if field not in node:
                errors.append(f"Missing required field '{field}' at {path}")

        # Validate field types
        if 'name' in node and not isinstance(node['name'], str):
            errors.append(f"Field 'name' must be string at {path}")

        if 'children' in node:
            if not isinstance(node['children'], list):
                errors.append(f"Field 'children' must be list at {path}")
            else:
                for i, child in enumerate(node['children']):
                    cls._validate_node(child, errors, f"{path}.children[{i}]")

        if 'label' in node and not isinstance(node['label'], str):
            errors.append(f"Field 'label' must be string at {path}")

        if 'description' in node and not isinstance(node['description'], str):
            errors.append(f"Field 'description' must be string at {path}")


class KnowledgeTreeUtils:
    """Utility functions for knowledge tree operations."""

    @staticmethod
    def count_nodes(tree: Dict[str, Any]) -> int:
        """Count total number of nodes in tree."""
        count = 1  # Count current node
        for child in tree.get('children', []):
            count += KnowledgeTreeUtils.count_nodes(child)
        return count

    @staticmethod
    def count_leaf_nodes(tree: Dict[str, Any]) -> int:
        """Count leaf nodes in tree."""
        if not tree.get('children'):
            return 1

        count = 0
        for child in tree['children']:
            count += KnowledgeTreeUtils.count_leaf_nodes(child)
        return count

    @staticmethod
    def get_max_depth(tree: Dict[str, Any]) -> int:
        """Get maximum depth of tree."""
        if not tree.get('children'):
            return 1

        max_child_depth = max(
            KnowledgeTreeUtils.get_max_depth(child) 
            for child in tree['children']
        )
        return 1 + max_child_depth

    @staticmethod
    def find_nodes_by_label(tree: Dict[str, Any], label: str) -> List[Dict[str, Any]]:
        """Find all nodes with specific label."""
        results = []

        if tree.get('label') == label:
            results.append(tree)

        for child in tree.get('children', []):
            results.extend(KnowledgeTreeUtils.find_nodes_by_label(child, label))

        return results

    @staticmethod
    def find_nodes_by_name_pattern(tree: Dict[str, Any], pattern: str) -> List[Dict[str, Any]]:
        """Find nodes with names matching pattern."""
        results = []

        if pattern.lower() in tree.get('name', '').lower():
            results.append(tree)

        for child in tree.get('children', []):
            results.extend(KnowledgeTreeUtils.find_nodes_by_name_pattern(child, pattern))

        return results

    @staticmethod
    def get_node_paths(tree: Dict[str, Any], target_node_name: str) -> List[str]:
        """Get all paths to nodes with specific name."""
        paths = []

        def _find_paths(node: Dict[str, Any], current_path: str):
            node_name = node.get('name', '')
            new_path = f"{current_path} -> {node_name}" if current_path else node_name

            if node_name == target_node_name:
                paths.append(new_path)

            for child in node.get('children', []):
                _find_paths(child, new_path)

        _find_paths(tree, "")
        return paths

    @staticmethod
    def extract_node_statistics(tree: Dict[str, Any]) -> Dict[str, Any]:
        """Extract comprehensive statistics from knowledge tree."""
        stats = {
            "total_nodes": KnowledgeTreeUtils.count_nodes(tree),
            "leaf_nodes": KnowledgeTreeUtils.count_leaf_nodes(tree),
            "max_depth": KnowledgeTreeUtils.get_max_depth(tree),
            "labels": {},
            "node_types": {},
            "has_source_info": 0,
            "nodes_with_descriptions": 0
        }

        def _collect_stats(node: Dict[str, Any]):
            # Count labels
            label = node.get('label', 'unknown')
            stats["labels"][label] = stats["labels"].get(label, 0) + 1

            # Count knowledge types
            kn_type = node.get('kn_type', 'unknown')
            stats["node_types"][kn_type] = stats["node_types"].get(kn_type, 0) + 1

            # Count nodes with source info
            if node.get('sourceList'):
                stats["has_source_info"] += 1

            # Count nodes with descriptions
            if node.get('description'):
                stats["nodes_with_descriptions"] += 1

            for child in node.get('children', []):
                _collect_stats(child)

        _collect_stats(tree)
        return stats


class KnowledgeTreeMerger:
    """Utility for merging multiple knowledge trees."""

    def __init__(self):
        self.merge_stats = ProcessingStats()

    def merge_trees(self, trees: List[Dict[str, Any]], merge_strategy: str = 'combine') -> Dict[str, Any]:
        """
        Merge multiple knowledge trees.

        Args:
            trees: List of trees to merge
            merge_strategy: Strategy for merging ('combine', 'union', 'intersect')

        Returns:
            Merged tree structure
        """
        if not trees:
            return {}

        if len(trees) == 1:
            return trees[0]

        logger.info(f"Merging {len(trees)} trees using strategy: {merge_strategy}")

        if merge_strategy == 'combine':
            return self._combine_trees(trees)
        elif merge_strategy == 'union':
            return self._union_trees(trees)
        elif merge_strategy == 'intersect':
            return self._intersect_trees(trees)
        else:
            raise ValueError(f"Unknown merge strategy: {merge_strategy}")

    def _combine_trees(self, trees: List[Dict[str, Any]]) -> Dict[str, Any]:
        """Combine trees by merging all nodes."""
        base_tree = trees[0].copy()

        for tree in trees[1:]:
            base_tree = self._merge_two_trees(base_tree, tree)

        return base_tree

    def _merge_two_trees(self, tree1: Dict[str, Any], tree2: Dict[str, Any]) -> Dict[str, Any]:
        """Merge two trees into one."""
        merged = tree1.copy()

        # Merge children
        merged_children = {}

        # Add children from first tree
        for child in tree1.get('children', []):
            key = child.get('name', '')
            merged_children[key] = child

        # Merge children from second tree
        for child in tree2.get('children', []):
            key = child.get('name', '')
            if key in merged_children:
                # Merge existing child
                merged_children[key] = self._merge_two_trees(merged_children[key], child)
            else:
                # Add new child
                merged_children[key] = child

        merged['children'] = list(merged_children.values())

        # Merge other fields
        for field in ['description', 'kn_type', 'sourceList']:
            if field in tree2 and field not in merged:
                merged[field] = tree2[field]
            elif field in tree2 and field in merged and field == 'sourceList':
                # Combine source lists
                merged[field] = merged[field] + tree2[field]

        return merged

    def _union_trees(self, trees: List[Dict[str, Any]]) -> Dict[str, Any]:
        """Create union of trees (all unique nodes)."""
        # Implementation for union merge
        return self._combine_trees(trees)  # Simplified for now

    def _intersect_trees(self, trees: List[Dict[str, Any]]) -> Dict[str, Any]:
        """Create intersection of trees (only common nodes)."""
        # Implementation for intersection merge
        return trees[0] if trees else {}  # Simplified for now


class KnowledgeTreeExporter:
    """Export knowledge trees to various formats."""

    @staticmethod
    def to_json(tree: Dict[str, Any], indent: int = 2) -> str:
        """Export tree to JSON string."""
        return json.dumps(tree, ensure_ascii=False, indent=indent)

    @staticmethod
    def to_file(tree: Dict[str, Any], filepath: Union[str, Path], format: str = 'json') -> None:
        """Export tree to file."""
        filepath = Path(filepath)

        if format == 'json':
            with open(filepath, 'w', encoding='utf-8') as f:
                json.dump(tree, f, ensure_ascii=False, indent=2)
        else:
            raise ValueError(f"Unsupported format: {format}")

        logger.info(f"Tree exported to {filepath}")

    @staticmethod
    def to_markdown(tree: Dict[str, Any], max_depth: int = 3) -> str:
        """Export tree structure to Markdown format."""
        lines = []

        def _node_to_markdown(node: Dict[str, Any], depth: int = 0):
            if depth > max_depth:
                return

            indent = "  " * depth
            name = node.get('name', 'Unnamed')
            description = node.get('description', '')
            label = node.get('label', '')

            # Add node header
            lines.append(f"{indent}- **{name}**")
            if label:
                lines.append(f"{indent}  - *Type*: {label}")
            if description:
                lines.append(f"{indent}  - *Description*: {description}")

            # Add children
            for child in node.get('children', []):
                _node_to_markdown(child, depth + 1)

        lines.append(f"# Knowledge Tree Structure\n")
        _node_to_markdown(tree)

        return "\n".join(lines)

    @staticmethod
    def to_mermaid(tree: Dict[str, Any]) -> str:
        """Export tree to Mermaid diagram format."""
        lines = ["graph TD"]
        node_id_map = {}
        node_counter = 0

        def _get_node_id(node_name: str) -> str:
            nonlocal node_counter
            if node_name not in node_id_map:
                node_id_map[node_name] = f"N{node_counter}"
                node_counter += 1
            return node_id_map[node_name]

        def _node_to_mermaid(node: Dict[str, Any], parent_id: Optional[str] = None):
            name = node.get('name', 'Unnamed')
            node_id = _get_node_id(name)

            # Add node definition
            safe_name = name.replace('"', "'")
            lines.append(f'    {node_id}["{safe_name}"]')

            # Add edge from parent
            if parent_id:
                lines.append(f"    {parent_id} --> {node_id}")

            # Process children
            for child in node.get('children', []):
                _node_to_mermaid(child, node_id)

        _node_to_mermaid(tree)
        return "\n".join(lines)


class ThreadSafeCounter:
    """Thread-safe counter for tracking processing progress."""

    def __init__(self):
        self._value = 0
        self._lock = threading.Lock()

    def increment(self, amount: int = 1) -> int:
        """Increment counter and return new value."""
        with self._lock:
            self._value += amount
            return self._value

    def decrement(self, amount: int = 1) -> int:
        """Decrement counter and return new value."""
        with self._lock:
            self._value -= amount
            return self._value

    @property
    def value(self) -> int:
        """Get current counter value."""
        with self._lock:
            return self._value

    def reset(self) -> None:
        """Reset counter to zero."""
        with self._lock:
            self._value = 0


class BatchProcessor:
    """Utility for batch processing of knowledge trees."""

    def __init__(self, max_workers: int = 4, batch_size: int = 10):
        self.max_workers = max_workers
        self.batch_size = batch_size
        self.stats = ProcessingStats()
        self.progress_counter = ThreadSafeCounter()

    def process_trees_batch(
        self, 
        trees: List[Dict[str, Any]], 
        processor_func: callable,
        **kwargs
    ) -> List[Dict[str, Any]]:
        """
        Process multiple trees in batches.

        Args:
            trees: List of trees to process
            processor_func: Function to process each tree
            **kwargs: Additional arguments for processor function

        Returns:
            List of processed trees
        """
        self.stats.total_nodes = len(trees)
        results = []

        logger.info(f"Processing {len(trees)} trees in batches of {self.batch_size}")

        with ThreadPoolExecutor(max_workers=self.max_workers) as executor:
            # Submit batches
            futures = []
            for i in range(0, len(trees), self.batch_size):
                batch = trees[i:i + self.batch_size]
                future = executor.submit(self._process_batch, batch, processor_func, **kwargs)
                futures.append(future)

            # Collect results
            for future in as_completed(futures):
                try:
                    batch_results = future.result()
                    results.extend(batch_results)
                    self.stats.processed_nodes += len(batch_results)
                except Exception as e:
                    error_msg = f"Batch processing failed: {e}"
                    self.stats.add_error(error_msg)
                    self.stats.failed_nodes += self.batch_size

        self.stats.mark_completed()
        logger.info(f"Batch processing completed: {self.stats.get_summary()}")

        return results

    def _process_batch(
        self, 
        batch: List[Dict[str, Any]], 
        processor_func: callable,
        **kwargs
    ) -> List[Dict[str, Any]]:
        """Process a single batch of trees."""
        results = []

        for tree in batch:
            try:
                result = processor_func(tree, **kwargs)
                results.append(result)
                self.progress_counter.increment()
            except Exception as e:
                error_msg = f"Tree processing failed: {e}"
                self.stats.add_error(error_msg)
                logger.error(error_msg)

        return results


class CacheManager:
    """Simple cache manager for processed trees."""

    def __init__(self, max_size: int = 1000):
        self.max_size = max_size
        self._cache: Dict[str, Dict[str, Any]] = {}
        self._access_order: List[str] = []
        self._lock = threading.Lock()

    def get_cache_key(self, tree: Dict[str, Any]) -> str:
        """Generate cache key for tree."""
        # Use tree name and hash of structure
        tree_str = json.dumps(tree, sort_keys=True, ensure_ascii=False)
        return hashlib.md5(tree_str.encode()).hexdigest()

    def get(self, key: str) -> Optional[Dict[str, Any]]:
        """Get item from cache."""
        with self._lock:
            if key in self._cache:
                # Move to end (most recently used)
                self._access_order.remove(key)
                self._access_order.append(key)
                return self._cache[key].copy()
            return None

    def put(self, key: str, value: Dict[str, Any]) -> None:
        """Put item in cache."""
        with self._lock:
            # Remove if already exists
            if key in self._cache:
                self._access_order.remove(key)

            # Add new item
            self._cache[key] = value.copy()
            self._access_order.append(key)

            # Evict if over capacity
            while len(self._cache) > self.max_size:
                oldest_key = self._access_order.pop(0)
                del self._cache[oldest_key]

    def clear(self) -> None:
        """Clear all cache."""
        with self._lock:
            self._cache.clear()
            self._access_order.clear()

    def size(self) -> int:
        """Get current cache size."""
        with self._lock:
            return len(self._cache)


def create_knowledge_processing_pipeline(
    max_workers: int = 4,
    batch_size: int = 10,
    enable_cache: bool = True
) -> Dict[str, Any]:
    """
    Create a complete knowledge processing pipeline with utilities.

    Args:
        max_workers: Maximum worker threads
        batch_size: Batch size for processing
        enable_cache: Whether to enable caching

    Returns:
        Dictionary containing all utility instances
    """
    pipeline = {
        'validator': KnowledgeTreeValidator(),
        'utils': KnowledgeTreeUtils(),
        'merger': KnowledgeTreeMerger(),
        'exporter': KnowledgeTreeExporter(),
        'batch_processor': BatchProcessor(max_workers, batch_size),
        'stats': ProcessingStats(),
        'counter': ThreadSafeCounter()
    }

    if enable_cache:
        pipeline['cache'] = CacheManager()

    logger.info(f"Knowledge processing pipeline created with {len(pipeline)} components")
    return pipeline


# Example usage functions
def validate_and_process_tree(tree: Dict[str, Any]) -> Tuple[bool, Dict[str, Any], List[str]]:
    """
    Validate tree and extract basic statistics.

    Args:
        tree: Knowledge tree to validate and process

    Returns:
        Tuple of (is_valid, statistics, errors)
    """
    # Validate tree
    is_valid, errors = KnowledgeTreeValidator.validate_tree(tree)

    # Extract statistics if valid
    stats = {}
    if is_valid:
        stats = KnowledgeTreeUtils.extract_node_statistics(tree)

    return is_valid, stats, errors


def export_tree_multiple_formats(
    tree: Dict[str, Any], 
    base_path: Union[str, Path],
    formats: List[str] = None
) -> Dict[str, str]:
    """
    Export tree to multiple formats.

    Args:
        tree: Knowledge tree to export
        base_path: Base path for output files
        formats: List of formats to export ('json', 'markdown', 'mermaid')

    Returns:
        Dictionary mapping format to output path
    """
    if formats is None:
        formats = ['json', 'markdown', 'mermaid']

    base_path = Path(base_path)
    outputs = {}

    for format_type in formats:
        try:
            if format_type == 'json':
                output_path = base_path.with_suffix('.json')
                KnowledgeTreeExporter.to_file(tree, output_path, 'json')
                outputs['json'] = str(output_path)

            elif format_type == 'markdown':
                output_path = base_path.with_suffix('.md')
                content = KnowledgeTreeExporter.to_markdown(tree)
                with open(output_path, 'w', encoding='utf-8') as f:
                    f.write(content)
                outputs['markdown'] = str(output_path)

            elif format_type == 'mermaid':
                output_path = base_path.with_suffix('.mmd')
                content = KnowledgeTreeExporter.to_mermaid(tree)
                with open(output_path, 'w', encoding='utf-8') as f:
                    f.write(content)
                outputs['mermaid'] = str(output_path)

        except Exception as e:
            logger.error(f"Failed to export to {format_type}: {e}")

    return outputs
